SELECT DISTINCT cp.id AS id FROM ( SELECT CASE WHEN attributed_name IS NOT NULL THEN 'name' WHEN creditor_id IS NOT NULL THEN 'creditor_id' WHEN counterparty_iban IS NOT NULL THEN 'iban' WHEN normalized_name <> '' THEN 'name' END AS identity_type, CASE WHEN attributed_name IS NOT NULL THEN upper(normalized_attributed) WHEN creditor_id IS NOT NULL THEN creditor_id WHEN counterparty_iban IS NOT NULL THEN counterparty_iban WHEN normalized_name <> '' THEN upper(normalized_name) END AS identity_value, remittance_info, counterparty_name, creditor_id, counterparty_iban, direction FROM ( SELECT creditor_id, counterparty_iban, counterparty_name, attributed_name, remittance_info, direction, trim(regexp_replace(normalize(counterparty_name, NFC), '\s+', ' ', 'g')) AS normalized_name, trim(regexp_replace(normalize(attributed_name, NFC), '\s+', ' ', 'g')) AS normalized_attributed FROM transactions WHERE split_parent_content_hash IS NULL ) normalized WHERE (CASE WHEN attributed_name IS NOT NULL THEN 'name' WHEN creditor_id IS NOT NULL THEN 'creditor_id' WHEN counterparty_iban IS NOT NULL THEN 'iban' WHEN normalized_name <> '' THEN 'name' END) IS NOT NULL ) t LEFT JOIN counterparty_alias al ON al.identity_type = t.identity_type AND al.identity_value = t.identity_value LEFT JOIN counterparties own ON own.identity_type = t.identity_type AND own.identity_value = t.identity_value JOIN counterparties cp ON cp.id = COALESCE(al.canonical_counterparty_id, own.id) WHERE cp.status <> 'dismissed'
